  "SimplePvPMod/src/main/resources/fabric.mod.json": "{\n  \"schemaVersion\": 1,\n  \"id\": \"simplepvp\",\n  \"version\": \"${version}\",\n  \"name\": \"SimplePvP\",\n  \"description\": \"Custom PvP Mod for DaraClient\",\n  \"authors\": [\n    \"DaraClient\"\n  ],\n  \"license\": \"MIT\",\n  \"environment\": \"client\",\n  \"entrypoints\": {\n    \"client\": [\n      \"com.example.SimplePvPClient\"\n    ]\n  },\n  \"mixins\": [\n    \"simplepvp.client.mixins.json\"\n  ],\n  \"depends\": {\n    \"fabricloader\": \">=0.15.0\",\n    \"minecraft\": \"~1.21.1\",\n    \"java\": \">=21\",\n    \"fabric-api\": \"*\"\n  }\n}\n",
